// Differential probe for the pinned examples/jsm/math/ConvexHull.js and
// examples/jsm/geometries/ConvexGeometry.js ports.
//
// Protocol: one scenario per stdin line, tokens separated by spaces. The scenario list is
// generated by compare-convex-hull.mjs, which replays the same calls against the pinned
// three.js modules, so the field order below is the single source of truth for both sides.
//
//   empty-hull
//   hull <count> <x> <y> <z> ...
//   hull-initial <count> <x> <y> <z> ...
//   hull-makeempty <count> <x> <y> <z> ...
//   hull-twice <count> <x y z>... <count> <x y z>...
//   hull-contains <count> <x y z>... <k> <x y z>...            (k query points)
//   hull-facedistance <count> <x y z>... <k> <x y z>...        (Face.distanceToPoint)
//   hull-ray <count> <x y z>... <origin3> <direction3>
//   hull-geometry <count> <x y z>...                           (ConvexGeometry arrays)
//
// The point coordinates travel as tokens because the differential oracle generates them once:
// the two sides then compute the hull from bit-identical binary64 inputs instead of depending
// on two math libraries with the same source text.
//
// `hull` dumps the exposed state after setFromPoints() (vertices, faces, half-edge links,
// vertex lists). `hull-initial` stops after _computeInitialHull(), which exposes the extremal
// vertices and a non-empty 'assigned' list. The source has no intersectLine, intersectsBox,
// intersectsSphere, distanceToPoint or closestPointToPoint on ConvexHull; Face.distanceToPoint
// is the only distance method of the pinned module and is covered by hull-facedistance.
//
// Numbers use the shared encoding of the other probes: NaN, -0, Infinity and -Infinity travel
// as those four strings.
#include "core/BufferAttribute.h"
#include "core/BufferGeometry.h"
#include "core/JsonValue.h"
#include "geometries/ConvexGeometry.h"
#include "math/ConvexHull.h"
#include "math/Ray.h"
#include "math/Vector3.h"
#include <charconv>
#include <cmath>
#include <cstddef>
#include <iostream>
#include <limits>
#include <memory>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

namespace {

JsonValue number(double value) {
    if (std::isnan(value)) return "NaN";
    if (std::isinf(value)) return value < 0 ? "-Infinity" : "Infinity";
    if (value == 0 && std::signbit(value)) return "-0";
    return value;
}
JsonValue vectorJSON(const Vector3& value) {
    return JsonValue::Array{number(value.x), number(value.y), number(value.z)};
}
double parse(const std::string& token) {
    if (token == "NaN") return std::numeric_limits<double>::quiet_NaN();
    if (token == "Infinity") return std::numeric_limits<double>::infinity();
    if (token == "-Infinity") return -std::numeric_limits<double>::infinity();
    if (token == "-0") return -0.;
    double value = 0;
    std::from_chars(token.data(), token.data() + token.size(), value);
    return value;
}

struct Reader {
    std::istringstream stream;
    explicit Reader(const std::string& line) : stream(line) {}
    std::string token() {
        std::string value;
        stream >> value;
        return value;
    }
    double numberToken() { return parse(token()); }
    bool hasMore() {
        stream >> std::ws;
        return stream.peek() != std::char_traits<char>::eof();
    }
    // Component order is fixed by sequential reads; argument evaluation order of a single call
    // expression would not be.
    Vector3 vector() {
        const double x = numberToken();
        const double y = numberToken();
        const double z = numberToken();
        return Vector3(x, y, z);
    }
    std::vector<Vector3> points() {
        const auto count = std::size_t(numberToken());
        std::vector<Vector3> result;
        result.reserve(count);
        for (std::size_t i = 0; i < count; ++i) result.push_back(vector());
        return result;
    }
};

// The pinned module has no such list: both sides enumerate the faces in `faces` order and walk
// each face cycle from `face.edge`, which gives the half edges a comparable numbering.
JsonValue indexOfEdge(const std::vector<const HalfEdge*>& edges, const HalfEdge* edge) {
    if (edge == nullptr) return JsonValue(nullptr);
    for (std::size_t i = 0; i < edges.size(); ++i)
        if (edges[i] == edge) return double(i);
    return JsonValue(nullptr);
}
JsonValue indexOfVertex(const std::vector<VertexNode*>& vertices, const VertexNode* vertex) {
    if (vertex == nullptr) return JsonValue(nullptr);
    for (std::size_t i = 0; i < vertices.size(); ++i)
        if (vertices[i] == vertex) return double(i);
    return JsonValue(nullptr);
}
JsonValue indexOfFace(const std::vector<Face*>& faces, const Face* face) {
    if (face == nullptr) return JsonValue(nullptr);
    for (std::size_t i = 0; i < faces.size(); ++i)
        if (faces[i] == face) return double(i);
    return JsonValue(nullptr);
}
// The 'assigned'/'unassigned' lists are walked through `next`, like the source does.
JsonValue vertexChain(const std::vector<VertexNode*>& vertices, const VertexNode* head) {
    JsonValue::Array chain;
    const VertexNode* vertex = head;
    for (std::size_t guard = 0; vertex != nullptr && guard < 4096; ++guard) {
        chain.push_back(indexOfVertex(vertices, vertex));
        vertex = vertex->next;
    }
    return chain;
}

JsonValue hullState(const ConvexHull& hull) {
    std::vector<const HalfEdge*> edges;
    for (const Face* face : hull.faces) {
        const HalfEdge* edge = face->edge;
        for (std::size_t guard = 0; edge != nullptr && guard < 64; ++guard) {
            edges.push_back(edge);
            edge = edge->next;
            if (edge == face->edge) break;
        }
    }

    JsonValue::Array vertices;
    for (const VertexNode* vertex : hull.vertices) {
        vertices.push_back(JsonValue::Object{{"point", vectorJSON(vertex->point)},
                                            {"prev", indexOfVertex(hull.vertices, vertex->prev)},
                                            {"next", indexOfVertex(hull.vertices, vertex->next)},
                                            {"face", indexOfFace(hull.faces, vertex->face)}});
    }

    JsonValue::Array faces;
    for (const Face* face : hull.faces) {
        JsonValue::Array faceEdges;
        const HalfEdge* edge = face->edge;
        for (std::size_t guard = 0; edge != nullptr && guard < 64; ++guard) {
            faceEdges.push_back(
                JsonValue::Object{{"vertex", indexOfVertex(hull.vertices, edge->vertex)},
                                  {"head", indexOfVertex(hull.vertices, edge->head())},
                                  {"tail", indexOfVertex(hull.vertices, edge->tail())},
                                  {"prev", indexOfEdge(edges, edge->prev)},
                                  {"next", indexOfEdge(edges, edge->next)},
                                  {"twin", indexOfEdge(edges, edge->twin)},
                                  {"face", indexOfFace(hull.faces, edge->face)},
                                  {"length", number(edge->length())},
                                  {"lengthSquared", number(edge->lengthSquared())},
                                  {"getEdgeMinus1", indexOfEdge(edges, face->getEdge(-1))},
                                  {"getEdge0", indexOfEdge(edges, face->getEdge(0))},
                                  {"getEdge1", indexOfEdge(edges, face->getEdge(1))},
                                  {"getEdge2", indexOfEdge(edges, face->getEdge(2))},
                                  {"getEdge3", indexOfEdge(edges, face->getEdge(3))}});
            edge = edge->next;
            if (edge == face->edge) break;
        }
        faces.push_back(JsonValue::Object{{"normal", vectorJSON(face->normal)},
                                         {"midpoint", vectorJSON(face->midpoint)},
                                         {"area", number(face->area)},
                                         {"constant", number(face->constant)},
                                         {"mark", double(face->mark)},
                                         {"outside", indexOfVertex(hull.vertices, face->outside)},
                                         {"edges", faceEdges}});
    }

    return JsonValue::Object{{"tolerance", number(hull.tolerance)},
                             {"vertices", vertices},
                             {"faces", faces},
                             {"newFaces", double(hull.newFaces.size())},
                             {"assignedEmpty", hull.assigned.isEmpty()},
                             {"unassignedEmpty", hull.unassigned.isEmpty()},
                             {"assignedHead", indexOfVertex(hull.vertices, hull.assigned.head)},
                             {"assignedTail", indexOfVertex(hull.vertices, hull.assigned.tail)},
                             {"assigned", vertexChain(hull.vertices, hull.assigned.head)},
                             {"unassignedHead",
                              indexOfVertex(hull.vertices, hull.unassigned.head)},
                             {"unassignedTail",
                              indexOfVertex(hull.vertices, hull.unassigned.tail)},
                             {"unassigned", vertexChain(hull.vertices, hull.unassigned.head)}};
}

JsonValue attributeValues(const BufferGeometry& geometry, const std::string& name) {
    const auto attribute = geometry.getAttribute(name);
    if (attribute == nullptr) return JsonValue(nullptr);
    JsonValue::Array values;
    for (double i = 0, count = attribute->getCount(); i < count; i++) {
        values.push_back(number(attribute->getX(i)));
        values.push_back(number(attribute->getY(i)));
        values.push_back(number(attribute->getZ(i)));
    }
    return values;
}

// Missing attributes are reported as null instead of dereferencing them, so a port that does
// not write them shows up as a diff rather than as a probe crash.
JsonValue sizeOf(const BufferGeometry& geometry, const std::string& name, bool itemSize) {
    const auto attribute = geometry.getAttribute(name);
    if (attribute == nullptr) return JsonValue(nullptr);
    return itemSize ? attribute->getItemSize() : attribute->getCount();
}

JsonValue geometryState(const ConvexGeometry& geometry) {
    return JsonValue::Object{{"type", geometry.type},
                             {"position", attributeValues(geometry, "position")},
                             {"normal", attributeValues(geometry, "normal")},
                             {"uv", attributeValues(geometry, "uv")},
                             {"hasPosition", geometry.hasAttribute("position")},
                             {"hasNormal", geometry.hasAttribute("normal")},
                             {"hasUv", geometry.hasAttribute("uv")},
                             {"positionItemSize", sizeOf(geometry, "position", true)},
                             {"normalItemSize", sizeOf(geometry, "normal", true)},
                             {"positionCount", sizeOf(geometry, "position", false)},
                             {"normalCount", sizeOf(geometry, "normal", false)},
                             {"indexIsNull", geometry.index == nullptr}};
}

JsonValue runScenario(const std::string& line) {
    Reader reader(line);
    const std::string kind = reader.token();

    if (kind == "empty-hull") {
        const ConvexHull hull;
        return hullState(hull);
    }

    if (kind == "hull") {
        ConvexHull hull;
        hull.setFromPoints(reader.points());
        return hullState(hull);
    }

    if (kind == "hull-initial") {
        const std::vector<Vector3> points = reader.points();
        ConvexHull hull;
        // The probe owns these nodes: the arena of a hull only owns the nodes it created
        // itself, and _computeInitialHull() links whatever this->vertices already holds.
        std::vector<std::unique_ptr<VertexNode>> owned;
        owned.reserve(points.size());
        for (const Vector3& point : points) {
            owned.push_back(std::make_unique<VertexNode>(point));
            hull.vertices.push_back(owned.back().get());
        }
        const ConvexHull::Extremes extremes = hull._computeExtremes();
        JsonValue::Array minIndices, maxIndices;
        for (int i = 0; i < 3; i++) {
            minIndices.push_back(indexOfVertex(hull.vertices, extremes.min[i]));
            maxIndices.push_back(indexOfVertex(hull.vertices, extremes.max[i]));
        }
        const double tolerance = hull.tolerance;
        hull._computeInitialHull();
        return JsonValue::Object{
            {"tolerance", number(tolerance)},
            {"min", minIndices},
            {"max", maxIndices},
            {"nextVertexToAdd", indexOfVertex(hull.vertices, hull._nextVertexToAdd())},
            {"state", hullState(hull)}};
    }

    if (kind == "hull-makeempty") {
        ConvexHull hull;
        hull.setFromPoints(reader.points());
        const bool returnedThis = &hull.makeEmpty() == &hull;
        return JsonValue::Object{{"returnedThis", returnedThis}, {"state", hullState(hull)}};
    }

    if (kind == "hull-twice") {
        ConvexHull hull;
        hull.setFromPoints(reader.points());
        // The second cloud replaces the first one through the makeEmpty() of setFromPoints().
        const bool returnedThis = &hull.setFromPoints(reader.points()) == &hull;
        return JsonValue::Object{{"returnedThis", returnedThis}, {"state", hullState(hull)}};
    }

    if (kind == "hull-contains") {
        ConvexHull hull;
        hull.setFromPoints(reader.points());
        const std::vector<Vector3> queries = reader.points();
        JsonValue::Array contains;
        for (const Vector3& query : queries) contains.push_back(hull.containsPoint(query));
        return JsonValue::Object{{"tolerance", number(hull.tolerance)}, {"contains", contains}};
    }

    if (kind == "hull-facedistance") {
        ConvexHull hull;
        hull.setFromPoints(reader.points());
        const std::vector<Vector3> queries = reader.points();
        JsonValue::Array distances;
        for (const Vector3& query : queries) {
            JsonValue::Array perFace;
            for (const Face* face : hull.faces)
                perFace.push_back(number(face->distanceToPoint(query)));
            distances.push_back(perFace);
        }
        return JsonValue::Object{{"distances", distances}};
    }

    if (kind == "hull-ray") {
        ConvexHull hull;
        hull.setFromPoints(reader.points());
        const Vector3 origin = reader.vector();
        const Vector3 direction = reader.vector();
        const Ray ray(origin, direction);
        Vector3 target;
        Vector3* hit = hull.intersectRay(ray, target);
        return JsonValue::Object{
            {"hit", hit != nullptr},
            {"point", hit != nullptr ? vectorJSON(target) : JsonValue(nullptr)},
            {"intersects", hull.intersectsRay(ray)}};
    }

    if (kind == "hull-geometry") {
        const ConvexGeometry geometry(reader.points());
        return geometryState(geometry);
    }

    throw std::runtime_error("unknown scenario kind: " + kind);
}

} // namespace

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        if (line.empty()) continue;
        try {
            std::cout << runScenario(line).dump() << '\n';
        } catch (const std::exception& error) {
            std::cout << JsonValue(JsonValue::Object{{"probeError", error.what()}}).dump() << '\n';
        }
    }
    return 0;
}
